arguments.command:
cat <<'EOF' | agent-browser eval --stdin
const rooms = document.querySelectorAll('[class*="room"], [class*="house"], [class*="card"], [class*="item"]');
const data = [];
document.querySelectorAll('.el-card, [class*="house-card"], [class*="room-item"], [class*="house-item"]').forEach(el => {
  data.push(el.innerText.trim().substring(0, 200));
});
if (data.length === 0) {
  // Try to get all visible text
  document.querySelectorAll('h4, [class*="room"], [class*="name"], [class*="title"]').forEach(el => {
    const text = el.innerText.trim();
    if (text) data.push(text);
  });
}
data;
EOF
